import{_ as t}from"./chunks/grundlagen-3.bPcOeDOj.js";import{_ as s,o as l,c as a,a3 as i,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const o="/bilder/reportdesigner/grundlagen-1.png",d="/bilder/reportdesigner/grundlagen-2.png",u="/bilder/reportdesigner/grundlagen-4.png",g="/bilder/reportdesigner/report-zeugnisse-0.png",p="/bilder/reportdesigner/report-zeugnisse-1.png",h="/bilder/reportdesigner/report-zeugnisse-2.png",R=JSON.parse('{"title":"Wie ein Report Daten zu einer Ausgabe zusammenführt","description":"","frontmatter":{"title":"Wie ein Report Daten zu einer Ausgabe zusammenführt","source_pageid":1564,"source_revision":6678},"headers":[],"relativePath":"reporting/reportdesigner/was-leistet-ein-report-in-schild-nrw-3.md","filePath":"reporting/reportdesigner/was-leistet-ein-report-in-schild-nrw-3.md"}'),m={name:"reporting/reportdesigner/was-leistet-ein-report-in-schild-nrw-3.md"};function c(b,r,f,w,k,z){return l(),a("div",null,[...r[0]||(r[0]=[i(`<h1 id="wie-ein-report-daten-zu-einer-ausgabe-zusammenfuhrt" tabindex="-1">Wie ein Report Daten zu einer Ausgabe zusammenführt <a class="header-anchor" href="#wie-ein-report-daten-zu-einer-ausgabe-zusammenfuhrt" aria-label="Permalink to &quot;Wie ein Report Daten zu einer Ausgabe zusammenführt&quot;">​</a></h1><p>Ein Report verbindet feste Gestaltung mit Datenbankfeldern. An einer Klassenliste und einem Zeugnis sehen Sie, wie aus der Vorlage die Ausgabe für die ausgewählten Schülerinnen und Schüler entsteht.</p><h2 id="was-leistet-ein-report-in-schild-nrw-3" tabindex="-1">Was leistet ein Report in SchILD-NRW 3? <a class="header-anchor" href="#was-leistet-ein-report-in-schild-nrw-3" aria-label="Permalink to &quot;Was leistet ein Report in SchILD-NRW 3?&quot;">​</a></h2><p>Ein <strong>Report</strong> in <strong>SchILD-NRW 3</strong> ist eine Vorlage, die beschreibt, wie Daten aus der Datenbank zu einem Dokument zusammengesetzt und ausgegeben werden sollen.</p><p>Ein Report enthält daher sowohl</p><ul><li><strong>Datenfelder</strong> (z. B. Vorname, Nachname, Geburtsdatum)</li></ul><p>als auch</p><ul><li><strong>Formatierungsanweisungen</strong> (z. B. Reihenfolge, Zeilenumbrüche, Schriftstile)</li></ul><p>Zum Beispiel könnte ein Report folgende Anweisung enthalten:</p><pre><code>    [VORNAME] [NACHNAME], [GEB_DATUM]
</code></pre><p>Die Begriffe in den eckigen Klammern stehen beispielhaft für <strong>Datenbankfelder</strong>. Beim Ausführen des Reports werden diese Felder für jeden ausgewählten Schüler mit den tatsächlichen Daten gefüllt.</p><p>Sind beispielsweise die Schüler „Simon Müller“ und „Lisa Heinz“ ausgewählt, würde das Ergebnis wie folgt aussehen:</p><pre><code>    Simon Müller, 09.08.2019
    Lisa Heinz, 23.07.2019
</code></pre><h2 id="beispiel-klassenliste" tabindex="-1">Beispiel: Klassenliste <a class="header-anchor" href="#beispiel-klassenliste" aria-label="Permalink to &quot;Beispiel: Klassenliste&quot;">​</a></h2><p>Als Beispiel soll eine Klassenliste analysiert werden.</p><h3 id="der-report-„klassenliste" tabindex="-1">Der Report „Klassenliste“ <a class="header-anchor" href="#der-report-„klassenliste" aria-label="Permalink to &quot;Der Report „Klassenliste“&quot;">​</a></h3><p><a href="/bilder/reportdesigner/grundlagen-1.png"><img src="`+o+'" alt="Die Anweisung, eine Klassenliste zu erzeugen." loading="lazy"></a></p><p><em>Die Anweisung, eine Klassenliste zu erzeugen.</em></p><p>In der Kopfzeile wird die Darstellung der Klassenliste festgelegt. Diese Kopfzeile ist farblich formatiert (blau/weiß) und bleibt bei der Ausgabe unverändert.</p><p>In der Zeile darunter befinden sich <strong>Datenfelder</strong>. Im Beispiel ist das Feld <strong>NameVorname</strong> hervorgehoben.</p><p>Jedes <strong>Datenfeld</strong> gehört zu einer <strong>Datenquelle</strong>. Die Datenquelle <strong>Schueler</strong> enthält z. B. Informationen wie</p><ul><li>Name</li><li>Geburtsdatum</li><li>aktuelle Klasse</li><li>Jahrgang</li><li>Bildungsgang</li></ul><p>und weitere Stammdaten.</p><p>Im Bild ist die Datenquelle <strong>Schueler</strong> oben links ausgewählt. Wurde eine Datenquelle ausgewählt, kann im danebenliegenden Dropdown ein konkretes <strong>Datenfeld</strong> gewählt werden, hier im Beispiel <strong>NameVorname</strong>.</p><p>Der Report ruft zusätzlich weitere Felder ab, u. a.</p><ul><li>die Klasse des jeweiligen Schülers</li><li>das aktuelle Schuljahr</li><li>den aktuellen Abschnitt (oben rechts)</li></ul><h3 id="klassenliste-drucken" tabindex="-1">Klassenliste drucken <a class="header-anchor" href="#klassenliste-drucken" aria-label="Permalink to &quot;Klassenliste drucken&quot;">​</a></h3><p><a href="/bilder/reportdesigner/grundlagen-2.png"><img src="'+d+'" alt="Erzeugen eines Reports aus einer fertigen Vorlage." loading="lazy"></a></p><p><em>Erzeugen eines Reports aus einer fertigen Vorlage.</em></p><p>Zunächst wird im Container die Gruppe ausgewählt, auf die der Report angewendet werden soll. Im Beispiel ist dies die Klasse <strong>5a</strong>.</p><p>Anschließend wird der Karteireiter <strong>Reportverwaltung</strong> geöffnet und in der Ordnerstruktur der gewünschte Report ausgewählt. Im Beispiel wird der Report <strong>Schüler-Klassenliste Geburtstagsliste</strong> mit einem Doppelklick gestartet.</p><p><a href="/bilder/reportdesigner/grundlagen-3.png"><img src="'+t+'" alt="Wahl der Ausgabe und ob die ganze Gruppe verarbeitet werden soll." loading="lazy"></a></p><p><em>Wahl der Ausgabe und ob die ganze Gruppe verarbeitet werden soll.</em></p><p>Über die Auswahl <strong>Ausgabe</strong> kann nun festgelegt werden, ob der Report sofort gedruckt oder zunächst als Vorschau angezeigt werden soll. Im Beispiel wird die Option <strong>Vorschau</strong> gewählt.</p><p><a href="/bilder/reportdesigner/grundlagen-4.png"><img src="'+u+'" alt="Die Klassenliste als Ergebnis." loading="lazy"></a></p><p><em>Die Klassenliste als Ergebnis.</em></p><p>In der Vorschau ist zu sehen, wie die festen Elemente des Reports (z. B. Kopfzeile) unverändert erscheinen, während die darunterstehenden Zeilen für jeden Schüler individuell aus der Datenbank befüllt werden.</p><p>Zusätzlich kann ein Report so konfiguriert werden, dass u. a. ausgegeben werden:</p><ul><li>Klassenleitungen</li><li>aktueller Abschnitt</li><li>automatische Nummerierungen</li><li>Seitenzahlen</li><li>Druckdatum und Uhrzeit</li><li>Dateiname des Reports</li></ul><h2 id="komplexe-reports-–-zum-beispiel-zeugnisse" tabindex="-1">Komplexe Reports – zum Beispiel Zeugnisse <a class="header-anchor" href="#komplexe-reports-–-zum-beispiel-zeugnisse" aria-label="Permalink to &quot;Komplexe Reports – zum Beispiel Zeugnisse&quot;">​</a></h2><p><a href="/bilder/reportdesigner/report-zeugnisse-0.png"><img src="'+g+'" alt="Ein Zeugnis als Beispiel für einen komplexen Report." loading="lazy"></a></p><p><em>Ein Zeugnis als Beispiel für einen komplexen Report.</em></p><p>Bei komplexen Reports wie Zeugnissen ist der Aufbau mehrstufig. Ein Hauptreport kann dabei weitere <strong>Unter-Reports</strong> aufrufen. Über Berechnungen und unterschiedliche Datenquellen wird das endgültige Dokument erzeugt.</p>',43),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),n("Beispiel")]),e("p",null,"Bei einem Zeugnis werden z. B. Leistungen aus mehreren Datenquellen zusammengeführt, abhängig vom aktuellen Abschnitt, den Fächereinstellungen und ggf. Abschlussregelungen.")],-1),i('<p><a href="/bilder/reportdesigner/report-zeugnisse-1.png"><img src="'+p+'" alt="In einem Zeugnis werden mehrere Seiten in einem Report erzeugt." loading="lazy"></a></p><p><em>In einem Zeugnis werden mehrere Seiten in einem Report erzeugt.</em></p><p>Das hier gezeigte Zeugnis besteht aus Vorder- und Rückseite. Auf der ersten Seite erscheinen die Leistungsdaten der für den Druck konfigurierten Fächer. SchILD-NRW 3 berücksichtigt außerdem Besonderheiten, etwa unterschiedliche Abschlussregelungen im Jahrgang 10 oder Lernbereichsnoten.</p><p>Über die Kopfzeile des Vorschaufensters können Zoomfaktor und Seitenwechsel gesteuert werden.</p><p><a href="/bilder/reportdesigner/report-zeugnisse-2.png"><img src="'+h+'" alt="In einem Zeugnis werden mehrere Seiten in einem Report erzeugt." loading="lazy"></a></p><p><em>In einem Zeugnis werden mehrere Seiten in einem Report erzeugt.</em></p><p>Auf der zweiten Seite erscheinen die im <strong>aktuellen Halbjahr</strong> erfassten Bemerkungen oder Zuweisungen. Eine mit dem Zeugnis gelieferte <code>.ini</code>-Datei legt unter anderem die Darstellung der Unterschriften fest, etwa Amtsbezeichnung sowie Vor- und Nachname.</p>',7),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Ein häufiges Fehlerbild: Das Entlassdatum erscheint als „30. Dezember 1899“. Dieses Datum bedeutet, dass für den aktuellen Abschnitt kein gültiges Datum gesetzt ist. Reports geben grundsätzlich das aus, was in der Datenbank hinterlegt ist.")],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Was_leistet_ein_Report_in_SchILD-NRW_3%3F",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 6678.")],-1)])])}const S=s(m,[["render",c]]);export{R as __pageData,S as default};
